def encode(frames):
    return ("\n".join(json.dumps(row, separators=(",", ":"), ensure_ascii=True)
                      for row in frames) + "\n").encode("ascii")


def frame(records, mode):
    return [{"schema": SCHEMA, "candidate": CANDIDATE, "catalog": CATALOG,
             "mode": mode, "count": len(records)}, *records,
            {"end": True, "count": len(records), "catalog": CATALOG}]


def fixtures():
    fixtures=[]
    source = copy.deepcopy(SOURCE)
    for row in source:
        row['types']['inputTypes'] = source[0]['types']['inputTypes']
        if row['kind'] == 'source-success':
            row['types']['resultTypes'] = source[0]['types']['resultTypes']
    for mode,records in [('target',TARGET),('source',source)]:
        base=frame(records,mode)
        def save(name,frames=None,data=None,valid=False):
            b=encode(frames if frames is not None else base) if data is None else data
            name=mode+'-'+name
            fixtures.append((name, mode, valid, b))
        save('valid',valid=True);save('no-final-newline',data=encode(base)[:-1],valid=True)
        for name,data in [('empty',b''),('header-only',encode(base[:1])),('no-footer',encode(base[:-1])),('truncated',encode(base)[:-3]),('after-footer',encode(base)+b'{}\n'),('extra-newline',encode(base)+b'\n'),('oversize',b' '*1048577),('nan',encode(base).replace(b'"gasUsed":"0"',b'"gasUsed":NaN',1)),('duplicate-key',encode(base).replace(b'"id":"S01"',b'"id":"S01","id":"S01"',1))]:save(name,data=data)
        def mutate(name,path,value,delete=False):
            f=copy.deepcopy(base);p=f
            for k in path[:-1]:p=p[k]
            if delete:del p[path[-1]]
            else:p[path[-1]]=value
            save(name,frames=f)
        for field in ['schema','candidate','catalog','mode','count']:mutate('header-'+field,[0,field],'bad')
        for field in ['end','count','catalog']:mutate('footer-'+field,[-1,field],False)
        mutate('unknown',[1,'extra'],0);mutate('missing',[1,'result'],None,True)
        mutate('duplicate-id',[2,'id'],'S01');mutate('wrong-kind',[1,'kind'],'raw')
        swapped=copy.deepcopy(base);swapped[1],swapped[2]=swapped[2],swapped[1];save('order',frames=swapped)
        for field in RESULT_FIELDS:
            for label,bad in [('bool',True),('int',0),('float',0.0),('negative','-1'),('leading-zero','00'),('plus','+0'),('unicode','٠'),('decimal','0.0'),('space',' 0'),('different','1')]:mutate('result-'+field+'-'+label,[1,'result',field],bad)
        for field in INPUT_FIELDS:
            mutate('input-'+field,[14,'input',field],'31')
