        for label,bad in [('minuszero','-0'),('leadingzero','-01'),('bool',False),('float',-1.0)]:mutate('state-'+label,[25,'input','stateSigned'],bad)
        for bad in ['-1',str(2**256),True,0]:mutate('refund-'+str(bad),[1,'input','refundUnsigned'],bad)
        f=copy.deepcopy(base);f[14]['result']['executionGasUsed'],f[14]['result']['stateGasUsed']=f[14]['result']['stateGasUsed'],f[14]['result']['executionGasUsed'];save('swapped-dimensions',frames=f)
        f=copy.deepcopy(base);f[14]['input']['gasLeft'],f[14]['input']['stateGasLeft']=f[14]['input']['stateGasLeft'],f[14]['input']['gasLeft'];save('swapped-returns',frames=f)
        if mode=='source':
            mutate('wrong-class',[1,'types','resultClass'],'other.TransactionGasSettlement')
            mutate('wrong-result-type',[1,'types','resultTypes',0],'builtins.int')
            mutate('wrong-input-type',[1,'types','inputTypes',4],'ethereum_types.numeric.Uint')
            mutate('wrong-error',[45,'error','class'],'builtins.ValueError')
